using Payments;

namespace Payments.Tests;

[TestClass]
public sealed class PaymentGatewayTests
{
    private PaymentGateway _gateway = null!;

    [TestInitialize]
    public void Init() => _gateway = new PaymentGateway();

    // ───── ChargeAsync ─────

    [TestMethod]
    public async Task ChargeAsync_ValidTokenAndAmount_ReturnsSuccessWithChargeId()
    {
        var result = await _gateway.ChargeAsync("tok_valid", 49.99m);

        Assert.IsTrue(result.Success);
        Assert.IsNotNull(result.ChargeId);
    }

    [TestMethod]
    [DataRow("")]
    [DataRow(null)]
    public async Task ChargeAsync_NullOrEmptyToken_ThrowsArgumentException(string? token)
    {
        await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.ChargeAsync(token!, 10m));
    }

    [TestMethod]
    [DataRow(0)]
    [DataRow(-1)]
    [DataRow(-100.50)]
    public async Task ChargeAsync_ZeroOrNegativeAmount_ThrowsArgumentOutOfRangeException(double amount)
    {
        await Assert.ThrowsExactlyAsync<ArgumentOutOfRangeException>(
            async () => await _gateway.ChargeAsync("tok_valid", (decimal)amount));
    }

    [TestMethod]
    public async Task ChargeAsync_DeclinedCard_ReturnsFailure()
    {
        var result = await _gateway.ChargeAsync("tok_declined", 25m);

        Assert.IsFalse(result.Success);
    }

    [TestMethod]
    [DataRow(0.01)]
    [DataRow(999_999.99)]
    public async Task ChargeAsync_BoundaryAmounts_ReturnsSuccess(double amount)
    {
        var result = await _gateway.ChargeAsync("tok_valid", (decimal)amount);

        Assert.IsTrue(result.Success);
        Assert.IsNotNull(result.ChargeId);
    }

    [TestMethod]
    public async Task ChargeAsync_ReturnsUniqueChargeIds()
    {
        var r1 = await _gateway.ChargeAsync("tok_valid", 10m);
        var r2 = await _gateway.ChargeAsync("tok_valid", 20m);

        Assert.AreNotEqual(r1.ChargeId, r2.ChargeId);
    }

    // ───── RefundAsync ─────

    [TestMethod]
    public async Task RefundAsync_ValidChargeId_ReturnsSuccessWithRefundId()
    {
        var charge = await _gateway.ChargeAsync("tok_valid", 50m);
        var refund = await _gateway.RefundAsync(charge.ChargeId);

        Assert.IsTrue(refund.Success);
        Assert.IsNotNull(refund.RefundId);
    }

    [TestMethod]
    [DataRow("")]
    [DataRow(null)]
    public async Task RefundAsync_NullOrEmptyChargeId_ThrowsArgumentException(string? chargeId)
    {
        await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.RefundAsync(chargeId!));
    }

    [TestMethod]
    public async Task RefundAsync_NonexistentChargeId_ReturnsFailure()
    {
        var result = await _gateway.RefundAsync("ch_nonexistent");

        Assert.IsFalse(result.Success);
    }

    [TestMethod]
    public async Task RefundAsync_DuplicateRefund_ThrowsInvalidOperationException()
    {
        var charge = await _gateway.ChargeAsync("tok_valid", 75m);
        await _gateway.RefundAsync(charge.ChargeId);

        await Assert.ThrowsExactlyAsync<InvalidOperationException>(
            async () => await _gateway.RefundAsync(charge.ChargeId));
    }

    // ───── ChargeResult / RefundResult records ─────

    [TestMethod]
    public void ChargeResult_EqualityByValue()
    {
        var a = new ChargeResult("ch_1", true);
        var b = new ChargeResult("ch_1", true);

        Assert.AreEqual(a, b);
    }

    [TestMethod]
    public void RefundResult_EqualityByValue()
    {
        var a = new RefundResult("rf_1", true);
        var b = new RefundResult("rf_1", true);

        Assert.AreEqual(a, b);
    }
}

